// Sweep health. A broken board token and a quiet market look identical from the dashboard,
// and a scheduled job nobody watches is one nobody notices failing. Silent when healthy.
const sweeps = items.map(i => i.json);
if (!sweeps.length) return [{ json: { content: '**huntpilot: no sweeps recorded at all.**' } }];

const latest = sweeps[0];
const started = new Date(latest.started_at).getTime();
const hours = (Date.now() - started) / 3600000;
const s = latest.summary || {};
const problems = [];

if (latest.state === 'failed') problems.push(`last sweep **failed**: ${latest.error || 'no reason recorded'}`);
if (latest.state === 'abandoned') problems.push('last sweep was **abandoned** — the worker died mid-run');
if (latest.state === 'running' && hours > 1) problems.push(`a sweep has been running for ${hours.toFixed(1)}h`);
if (hours > 13) problems.push(`no sweep for **${hours.toFixed(1)}h** — Beat runs every 6h, so it is not scheduling`);
if ((s.boards_failed || 0) > 0) problems.push(`**${s.boards_failed} board(s) failed** to load — likely a stale token`);

if (!problems.length) return [];
return [{ json: { content: ['**huntpilot sweep problem**', ...problems.map(p => `• ${p}`)].join('\n') } }];
